 * BBCode → HTML converter.
 *
 * Architecture: a single-pass cursor-based tokenizer + an explicit tag stack.
 * No regex soup — tags are recognized by one anchored grammar regex, and all
 * nesting decisions are made by the stack.
 *
 * Nesting rules (documented contract):
 *
 * 1. Auto-close rule. When a closing tag arrives whose matching opener is
 *    buried under other open tags, every tag opened *after* it is implicitly
 *    closed first (rendered with its proper HTML end tag), and nothing is
 *    reopened. Example:
 *
 *        [b][i]x[/b]  ->  <strong><em>x</em></strong>
 *
 *    The <em> is closed early by the auto-close; it is NOT reopened after
 *    [/b], and any text following [/b] is outside both tags.
 *
 * 2. Unknown tags render as literal (escaped) text. A known tag whose closing
 *    counterpart never appears (unclosed at EOF) also renders as literal
 *    text for its own source, while its properly-parsed children still
 *    render normally. Example:
 *
 *        [b]x      ->  [b]x
 *        [foo]bar[/foo]  ->  [foo]bar[/foo]
 *
 * 3. [code] content is fully escaped verbatim; inner BBCode inside a closed
 *    code block is ignored entirely. An unterminated [code] falls back to
 *    rule 2 (the opening tag becomes literal text).
 *
 * 4. URL targets go through a scheme allowlist (http, https, mailto, ftp).
 *    Anything else with a scheme — javascript:, data:, vbscript:, ... — makes
 *    the whole tag render as plain escaped text.
 */

// ---------------------------------------------------------------------------
// HTML escaping
// ---------------------------------------------------------------------------

const ESCAPES: Record<string, string> = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;",
};

export function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ESCAPES[c]);
}

// ---------------------------------------------------------------------------
// URL scheme allowlist
// ---------------------------------------------------------------------------

/** Only these schemes are allowed in url targets / href attributes. */
const ALLOWED_SCHEMES = new Set(["http:", "https:", "mailto:", "ftp:"]);

/**
 * True when `url` is either scheme-relative/relative or uses an allowlisted
 * scheme. Control characters and whitespace are stripped before scheme
 * detection so `java\tscript:` cannot smuggle through.
 */
export function isSafeUrl(url: string): boolean {
  const stripped = url.trim().replace(/[\u0000-\u0020]+/g, "");
  const m = /^([a-zA-Z][a-zA-Z0-9+.-]*):/.exec(stripped);
  if (!m) return true; // relative URL — no scheme to abuse
  try {
    return ALLOWED_SCHEMES.has(new URL(stripped).protocol);
  } catch {
    return false;
  }
}

// ---------------------------------------------------------------------------
// AST
// ---------------------------------------------------------------------------

export interface BbTextNode {
  type: "text";
  value: string;
}

export interface BbTagNode {
  type: "tag";
  /** Lowercased tag name; "*" for [*] list items, "" for the root frame. */
  name: string;
  /** Attribute after "=", quotes stripped, undefined when absent. */
  attr?: string;
  /** Exact source of the opening tag (or "[*]"), used for literal fallbacks. */
  raw: string;
  /**
   * Source of the matching explicit close tag when the node was closed by
   * one; undefined for auto-closed nodes and unclosed nodes.
   */
  closeRaw?: string;
  /** False when the tag was auto-closed by an outer [/tag] or hit EOF open. */
  closed: boolean;
  children: BbNode[];
  /** Verbatim inner text, set only for [code]. */
  rawContent?: string;
}

export type BbNode = BbTextNode | BbTagNode;

// ---------------------------------------------------------------------------
// Tokenizer + parser (single pass over a cursor)
// ---------------------------------------------------------------------------

/**
 * Grammar for one tag at the current position:
 *   "[" ("/")? name ("=" attr)? "]"
 * name: "*" or letter followed by letters/digits. attr: anything but "[" or "]".
 */
const TAG_RE = /^\[(\/?)(\*|[a-zA-Z][a-zA-Z0-9]*)((?:=[^[\]]*)?)\]/;

function stripQuotes(attr: string): string {
  if (
    attr.length >= 2 &&
    ((attr.startsWith('"') && attr.endsWith('"')) ||
      (attr.startsWith("'") && attr.endsWith("'")))
  ) {
    return attr.slice(1, -1);
  }
  return attr;
}

interface Frame {
  name: string;
  attr?: string;
  raw: string;
  closeRaw?: string;
  closed: boolean;
  children: BbNode[];
}

function newFrame(name: string, raw: string, attr?: string): Frame {
  return { name, raw, attr, closed: false, children: [] };
}

/**
 * Parse BBCode into a tree rooted at an anonymous frame. The stack discipline
 * implements the documented rules: explicit closes pop their opener plus
 * everything above it (auto-close, no reopening); unmatched closes and
 * unterminated opens are flagged for literal rendering.
 */
function parse(input: string): Frame {
  const root = newFrame("", "");
  const stack: Frame[] = [root];
  let pos = 0;

  // Ensure non-item children of a [list] land in an implicit current item.
  function pushChild(child: BbNode): void {
    const top = stack[stack.length - 1];
    if (top.name === "list" && child.type !== "tag") {
      let last = top.children[top.children.length - 1];
      if (!last || last.type !== "tag" || last.name !== "*") {
        last = {
          type: "tag",
          name: "*",
          raw: "[*]",
          closed: true,
          children: [],
        } satisfies BbTagNode;
        top.children.push(last);
      }
      (last as BbTagNode).children.push(child);
      return;
    }
    top.children.push(child);
  }

  function emitText(text: string): void {
    if (text) pushChild({ type: "text", value: text });
  }

  while (pos < input.length) {
    const ch = input[pos];

    if (ch !== "[") {
      const nextBracket = input.indexOf("[", pos);
      const end = nextBracket === -1 ? input.length : nextBracket;
      emitText(input.slice(pos, end));
      pos = end;
      continue;
    }

    const m = TAG_RE.exec(input.slice(pos));
    if (!m) {
      // Stray bracket that does not form a valid tag: literal text.
      emitText("[");
      pos += 1;
      continue;
    }
    const raw = m[0];
    const isClose = m[1] === "/";
    const name = m[2].toLowerCase();
    const attrRaw = m[3] === undefined ? undefined : m[3].slice(1);

    if (isClose) {
      const closeRaw = raw;
      // Find the nearest open frame with this name.
      let idx = -1;
      for (let i = stack.length - 1; i > 0; i--) {
        if (stack[i].name === name && name !== "") {
          idx = i;
          break;
        }
      }
      if (idx === -1) {
        // Unmatched close tag: literal text (rule 2).
        emitText(closeRaw);
      } else {
        // Auto-close everything above it — closed early, NOT reopened.
        while (stack.length - 1 > idx) {
          const orphan = stack.pop()!;
          orphan.closed = false;
          if (orphan.name === "code") {
            delete (orphan as BbTagNode).rawContent;
          }
        }
        const opened = stack.pop()!;
        opened.closed = true;
        opened.closeRaw = closeRaw;
        pushChild(frameToNode(opened));
      }
      pos += raw.length;
      continue;
    }

    // Opening tag.
    if (name === "*") {
      // [*] only means something directly usable inside a [list].
      let inList = false;
      for (let i = stack.length - 1; i > 0; i--) {
        if (stack[i].name === "list") {
          inList = true;
          break;
        }
      }
      if (!inList) {
        emitText(raw);
        pos += raw.length;
        continue;
      }
      const item = newFrame("*", raw);
      item.closed = true;
      stack[stack.length - 1].children.push(frameToNode(item));
      stack.push(item);
      pos += raw.length;
      continue;
    }

    if (name === "code") {
      // Consume verbatim up to the first [/code]; inner BBCode is ignored.
      const rest = input.slice(pos + raw.length);
      const closeMatch = /\[\/code\]/i.exec(rest);
      if (closeMatch) {
        const content = rest.slice(0, closeMatch.index);
        const frame = newFrame("code", raw);
        frame.closed = true;
        frame.closeRaw = closeMatch[0];
        frame.children = [
          { type: "text", value: "" },
        ];
        (frame as BbTagNode).rawContent = content;
        pushChild(frameToNode(frame));
        pos += raw.length + closeMatch.index + closeMatch[0].length;
      } else {
        // Unterminated [code]: fall back to normal handling (rule 3/2);
        // EOF will leave it unclosed => literal rendering.
        const frame = newFrame("code", raw);
        stack.push(frame);
        pos += raw.length;
      }
      continue;
    }

    const frame = newFrame(name, raw, attrRaw === undefined ? undefined : stripQuotes(attrRaw));
    stack.push(frame);
    pos += raw.length;
  }

  // EOF: whatever is still open stays unclosed => literal rendering (rule 2).
  while (stack.length > 1) {
    const orphan = stack.pop()!;
    orphan.closed = false;
    if (orphan.name === "code") delete (orphan as BbTagNode).rawContent;
    pushChild(frameToNode(orphan));
  }

  return root;
}

function frameToNode(f: Frame): BbTagNode {
  return {
    type: "tag",
    name: f.name,
    attr: f.attr,
    raw: f.raw,
    closeRaw: f.closeRaw,
    closed: f.closed,
    children: f.children,
    rawContent: (f as BbTagNode).rawContent,
  };
}

// ---------------------------------------------------------------------------
// Renderer
// ---------------------------------------------------------------------------

function renderChildren(node: BbTagNode): string {
  return node.children.map(renderNode).join("");
}

function renderNode(node: BbNode): string {
  if (node.type === "text") return escapeHtml(node.value);

  const inner = renderChildren(node);

  // Unclosed tags degrade to literal text, except list items which always
  // wrap in <li> (an implicit final item may legitimately lack [/list]-time
  // closing because [*] has no end tag of its own).
  if (!node.closed) {
    if (node.name === "*") return `<li>${inner}</li>`;
    return `${escapeHtml(node.raw)}${inner}`;
  }

  switch (node.name) {
    case "":
      return inner;
    case "b":
      return `<strong>${inner}</strong>`;
    case "i":
      return `<em>${inner}</em>`;
    case "u":
      return `<u>${inner}</u>`;
    case "code":
      // Fully escaped verbatim content; no child rendering at all.
      return `<pre><code>${escapeHtml(node.rawContent ?? "")}</code></pre>`;
    case "url": {
      const target = node.attr ?? "";
      if (!target || !isSafeUrl(target)) {
        // Unsafe target: whole opening tag degrades to plain text.
        return `${escapeHtml(node.raw)}${inner}${node.closeRaw ? escapeHtml(node.closeRaw) : ""}`;
      }
      return `<a href="${escapeHtml(target)}">${inner}</a>`;
    }
    case "quote":
      return node.attr !== undefined
        ? `<blockquote><cite>${escapeHtml(node.attr)}</cite>${inner}</blockquote>`
        : `<blockquote>${inner}</blockquote>`;
    case "list":
      return `<ul>${inner}</ul>`;
    case "*":
      return `<li>${inner}</li>`;
    default:
      // Unknown-but-closed tag: literal source around rendered children.
      return `${escapeHtml(node.raw)}${inner}${node.closeRaw ? escapeHtml(node.closeRaw) : ""}`;
  }
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/** Convert BBCode to HTML per the rules documented at the top of this file. */
export function bbcodeToHtml(input: string): string {
  return renderChildren(parse(input));
}
