// ---------------------------------------------------------------------------
// HTML escaping
// ---------------------------------------------------------------------------

const ESCAPES: Record<string, string> = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;",
};

export function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ESCAPES[c]);
}

// ---------------------------------------------------------------------------
// URL scheme allowlist
// ---------------------------------------------------------------------------

/** Only these schemes are allowed in url targets. */
const ALLOWED_SCHEMES = new Set(["http:", "https:", "mailto:", "ftp:"]);

/**
 * True when `url` is relative/scheme-relative or uses an allowlisted scheme.
 * Whitespace and control characters are stripped before scheme detection so
 * `jav\tascript:` cannot smuggle through.
