        unwindTo(idx); // auto-close intermediates, no reopening (rule 1)
        const opened = stack.pop()!;
        opened.status = "closed";
        opened.closeRaw = raw;
        pushChild(toNode(opened));
      }
      pos += raw.length;
      continue;
    }

    // --- opening tags ---

    if (name === "*" && !attrRaw) {
      // [*] closes the previous item, then opens one inside the nearest list.
      let listIdx = -1;
      for (let i = stack.length - 1; i > 0; i--) {
        if (stack[i].name === "list") {
          listIdx = i;
          break;
        }
      }
      if (listIdx === -1) {
        emitText(raw); // [*] outside any [list]: literal text
        pos += raw.length;
        continue;
      }
      unwindTo(listIdx);
      const item = newFrame("*", raw);
      item.status = "closed"; // [*] has no end tag; never degrades
      stack.push(item);
      pos += raw.length;
      continue;
    }

    if (name === "code") {
      // Consume verbatim up to the first [/code]; inner BBCode is ignored.
      const rest = input.slice(pos + raw.length);
      const closeMatch = /\[\/code\]/i.exec(rest);
      if (closeMatch) {
        const frame = newFrame("code", raw);
        frame.status = "closed";
        frame.closeRaw = closeMatch[0];
        const node = toNode(frame);
        node.rawContent = rest.slice(0, closeMatch.index);
        pushChild(node);
        pos += raw.length + closeMatch.index + closeMatch[0].length;
      } else {
        // Unterminated [code]: parse contents normally; EOF leaves the frame
        // "eof" so it degrades to literal rendering (rule 3 -> rule 2).
        stack.push(newFrame("code", raw));
        pos += raw.length;
      }
      continue;
    }

    const attr =
      attrRaw === undefined ? undefined : stripQuotes(attrRaw.slice(1));
    stack.push(newFrame(name, raw, attr));
    pos += raw.length;
  }

  // EOF: frames still open keep their "eof" status => literal fallback.
  while (stack.length > 1) popAndAttach();

  return root;
}

// ---------------------------------------------------------------------------
// Renderer
// ---------------------------------------------------------------------------

function renderNodes(children: BbNode[]): string {
  return children.map(renderNode).join("");
}

function renderNode(node: BbNode): string {
  if (node.type === "text") return escapeHtml(node.value);

  const inner = renderNodes(node.children);

  switch (node.name) {
    case "":
      return inner;
    case "*":
      // [*] has no end tag of its own; always wraps as a list item.
      return `<li>${inner}</li>`;
    case "code":
      if (node.rawContent !== undefined) {
        // Fully escaped verbatim content; child rendering bypassed entirely.
        return `<pre><code>${escapeHtml(node.rawContent)}</code></pre>`;
      }
      // Unterminated code block: literal opening tag + rendered contents.
      return `${escapeHtml(node.raw)}${inner}`;
    default: {
      const unknown = !KNOWN_TAGS.has(node.name);
      if (unknown || node.status === "eof") {
        // Unknown tags, or known tags unclosed at EOF: literal source around
        // whatever parsed cleanly inside.
        const tail = node.closeRaw ? escapeHtml(node.closeRaw) : "";
        return `${escapeHtml(node.raw)}${inner}${tail}`;
      }
      // Known tag, closed explicitly ("closed") or auto-closed ("auto").
      switch (node.name) {
        case "b":
          return `<strong>${inner}</strong>`;
        case "i":
          return `<em>${inner}</em>`;
        case "u":
          return `<u>${inner}</u>`;
        case "url": {
          const target = node.attr ?? "";
          if (!target || !isSafeUrl(target)) {
            // Unsafe target: whole tag degrades to plain text (rule 4).
            const tail = node.closeRaw ? escapeHtml(node.closeRaw) : "";
            return `${escapeHtml(node.raw)}${inner}${tail}`;
          }
          return `<a href="${escapeHtml(target)}">${inner}</a>`;
        }
        case "quote":
          return node.attr !== undefined
            ? `<blockquote><cite>${escapeHtml(node.attr)}</cite>${inner}</blockquote>`
            : `<blockquote>${inner}</blockquote>`;
        case "list":
          return `<ul>${inner}</ul>`;
        default:
          return inner; // unreachable
      }
    }
  }
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/** Convert BBCode to HTML per the rules documented at the top of this file. */
export function bbcodeToHtml(input: string): string {
  return renderNodes(parse(input).children);
}
